from __future__ import annotations
from .canonical import content_hash,stable_id
from .authority import authority_boundary

def build(receipt,dataset_summary,reward_audit,behavior,support_bundle,ope_bundle,challenge_matrix,stress_bundle,budget,baseline_matrix,trial_ledger,exposure_ledger):
    gates={'upstream_verified':receipt['verified'],'dataset_validated':dataset_summary['episode_count']>=4,'reward_audit_passed':reward_audit['passed'],'support_reports_complete':all(x['passed'] for x in support_bundle.values()),'ope_complete':all(set(x['estimators'])=={'wis','pdis','fqe','doubly_robust'} for x in ope_bundle.values()),'synthetic_veto_complete':all(x['synthetic_positive_evidence'] is False for x in stress_bundle.values()),'baseline_preserved':baseline_matrix['passed'],'hidden_evaluation_queries_zero':budget['counts']['hidden_evaluation_queries']==0,'protected_evidence_exposures_zero':budget['counts']['protected_evidence_exposures']==0,'trial_ledger_complete':trial_ledger['complete'],'exposure_ledger_complete':exposure_ledger['complete']}
    out={'phase':'SAED_V4_23','certificate_id':stable_id('offline_policy_research_certificate',{'receipt':receipt['receipt_hash'],'matrix':challenge_matrix['matrix_hash']}),'accepted_for_offline_policy_research':all(gates.values()),'research_selected_policy_id':challenge_matrix['selected_research_policy_id'],'selection_is_research_only':True,'gates':gates,'upstream_receipt_hash':receipt['receipt_hash'],'dataset_summary_hash':dataset_summary['summary_hash'],'reward_audit_hash':reward_audit['audit_hash'],'behavior_policy_hash':behavior['policy_hash'],'challenge_matrix_hash':challenge_matrix['matrix_hash'],'budget_ledger_hash':budget['ledger_hash'],'trial_ledger_hash':trial_ledger['ledger_hash'],'exposure_ledger_hash':exposure_ledger['ledger_hash'],'authority_boundary':authority_boundary(),'promotion_authority':False,'runtime_executable':False,'production_authority':False,'real_alpha_claim':False,'prospective_success_claim':False}
    out['certificate_hash']=content_hash(out);return out
